599	    public Person add(String user, String sheetId, String name, String grade) {
600	        requireSheet(sheetId);
601	        String trimmed = name.trim();
602	        requireNameFree(sheetId, trimmed, null);
603	        Person person = people.saveAndFlush(new Person(sheetId, trimmed, grade));
604	        audit.recordOnCommit(entry("PERSON_ADDED", user, person));
605	        return person;
606	    }
607	
608	    @Transactional
609	    public Person update(String user, String sheetId, Long id, String name, String grade) {
610	        Person person = people.findByIdAndSheetId(id, sheetId)
611	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
612	        String trimmed = name.trim();
613	        requireNameFree(sheetId, trimmed, id);
614	        person.setName(trimmed);
615	        person.setGrade(grade);
616	        people.flush();
617	        audit.recordOnCommit(entry("PERSON_EDITED", user, person));
618	        return person;
619	    }
