426	export function dueOf(amount: string, rate: string | undefined): string {
427	  if (rate === undefined) return NO_RATE;
428	  // cents × hundredths of a percent is in millionths; round to cents (amounts are never negative).
429	  const cents = (hundredths(amount) * hundredths(rate) + 5000n) / 10000n;
430	  return `${cents / 100n}.${String(cents % 100n).padStart(2, '0')}`;
